 async save(next){
  if(!this.ready||this.locked){toast('Unlock your workspace first.');return false;}
  if(this.busy){toast('A save is already in progress. Please try again.');return false;}
  this.busy=true;
  let undo=()=>{};try{T.validate(next);undo=TracklyLicense.reserve(state,next);await this.repo.save(next);state=next;storageError=false;storageIssue='';rawStored=null;this.channel?.postMessage({type:'changed',revision:this.repo.revision,encrypted:this.repo.encrypted});this.touch();return true;}
  catch(e){try{undo();}catch{}toast('Could not save: '+e.message+'. Existing saved records are unchanged.');return false;}finally{this.busy=false;}
 },
 scope(){return FeatureData.scope(state,this.member);},
 view(fn){const full=state;try{state=this.scope();return fn();}finally{state=full;}},
 filterBar(){if(['family','reports','settings','coverage','contacts','scanner','help'].includes(page))return '';return '<div class="family-filter no-print"><label for="family-filter">Viewing</label><select id="family-filter">'+[['all','All family members'],...state.members.map(m=>[m.id,m.name])].map(([id,label])=>'<option value="'+esc(id)+'" '+(id===this.member?'selected':'')+'>'+esc(label)+'</option>').join('')+'</select><span>'+esc(this.repo.encrypted?'Encrypted workspace · unlocked':'Saved on this device')+'</span>'+(this.repo.encrypted?btn('Lock','vault-lock'):'')+'</div>';},
 cleanBlobs(){for(const url of this.blobs)URL.revokeObjectURL(url);this.blobs=[];},
