 return heading('Bill & EOB comparison','Compare the original documents with the amounts you entered.',btn('Add document','new-document',b.id,'primary'))+billPicker('compare-record',b.id,s)+'<div class="comparison-amounts">'+[['Billed',b.billed],['Allowed',b.allowed],['Insurance paid',b.insurancePaid],['EOB responsibility',b.patientOwes],['Provider balance',b.providerBalance],['Still owed',T.balance(s,b)]].map(([label,value])=>'<div><small>'+label+'</small><strong>'+(value===null?'Unknown':cash(value))+'</strong></div>').join('')+'<div class="notice"><div><h3>'+(T.review(s,b)?'Review required':'Recorded amounts in view')+'</h3><p>A difference is a reason to check the bill and EOB. Amounts shown here come from your entries.</p></div>'+btn('Edit amounts','edit-bill',b.id)+'</div><div class="compare-grid">'+panel('Medical bill','<div class="panel-body">'+selector('left',left)+'</div>')+panel('Explanation of Benefits','<div class="panel-body">'+selector('right',right)+'</div>')+'</div>';
