 return heading('Your report studio','Choose the family member, dates, records and documents to include.',reportButtons())+'<div class="filter-pills">'+btn('All records','report-preset','all')+state.members.map(m=>btn(m.name,'report-preset',m.id)).join('')+'</div><div class="report-layout">'+panel('Build your report','<div class="panel-body report-options">'+reportControls()+'<label class="field">Family member<select id="report-member"><option value="all">All family members</option>'+state.members.map(m=>'<option value="'+esc(m.id)+'" '+(o.memberId===m.id?'selected':'')+'>'+esc(m.name)+'</option>').join('')+'</select></label><label class="field">Service date from<input type="date" id="report-from" value="'+esc(o.from)+'"></label><label class="field">Service date to<input type="date" id="report-to" value="'+esc(o.to)+'"></label><label class="check-label"><input type="checkbox" id="report-notes" '+(o.mode==='full'?'checked disabled':o.notes?'checked':'')+'> Include claim notes</label><label class="check-label"><input type="checkbox" id="report-timeline" '+(o.mode==='full'?'checked disabled':o.timeline?'checked':'')+'> Include timeline history</label><p class="hint">Period filters medical service dates, including both endpoints. Linked payments and claim history are included in full. Full report includes EOB amounts, appeals, plans, coverage and actions. Selected attachments are appended as PDF pages.</p></div>')+panel('Report preview','<div class="panel-body"><span class="eyebrow">MEDICAL EXPENSE SUMMARY</span><h2>'+selected.bills.length+' selected records</h2><p class="report-period-label">'+esc(reportPeriodLabel())+' · Currency: '+esc(T.currency(state))+'</p>'+(o.from&&o.to&&o.from>o.to?'<p class="form-error" role="alert">Choose an end date on or after the start date.</p>':'')+'<div class="comparison-amounts">'+[['Billed',totals.billed],['Insurance paid',totals.insurance],['You paid',totals.paid],['Still owed',totals.owed]].map(([l,v])=>'<div><small>'+l+'</small><strong>'+cash(v)+'</strong></div>').join('')+'</div><p class="hint">'+totals.unknown+' with unknown responsibility · '+(o.documentIds||[]).filter(id=>docs.some(d=>d.id===id)).length+' attached documents</p>'+reportButtons()+'</div>')+'</div>'+panel('Choose medical records','<div class="report-selection"><label class="check-label"><input type="checkbox" id="report-all" '+(o.billIds===null?'checked':'')+'> Select all matching records</label>'+eligible.bills.map(b=>'<label class="check-label"><input type="checkbox" data-report-bill="'+esc(b.id)+'" '+(o.billIds===null||o.billIds.includes(b.id)?'checked':'')+'><span><strong>'+esc(b.provider)+'</strong><small>'+esc(b.patient)+' · '+fmtDate(b.serviceDate)+' · '+cash(b.billed)+'</small></span></label>').join('')+'</div>')+panel('Attach supporting documents','<div class="report-selection">'+(docs.length?docs.map(d=>'<label class="check-label"><input type="checkbox" data-report-document="'+esc(d.id)+'" '+(o.documentIds.includes(d.id)?'checked':'')+'><span>'+esc(d.name)+'<small>'+esc(d.type)+' · '+esc(state.bills.find(b=>b.id===d.billId)?.provider||'Unlinked')+'</small></span></label>').join(''):'<p class="hint">No documents linked to the selected records.</p>')+'</div>');
