document.addEventListener('submit',async e=>{
 if(e.target.id!=='vault-unlock-form')return;e.preventDefault();const button=e.target.querySelector('button[type="submit"]');button.disabled=true;try{await FeatureKit.unlock(new FormData(e.target).get('password'));}catch(err){const output=$('#unlock-error');if(output)output.textContent=err.message;}finally{button.disabled=false;}
});
document.addEventListener('change',async e=>{
 const el=e.target;if(!FeatureKit.ready)return;
 try{
  if(el.id==='family-filter'){FeatureKit.member=el.value;render();}
  if(el.id==='compare-record'){FeatureKit.compareBill=el.value;FeatureKit.leftDoc='';FeatureKit.rightDoc='';render();}
  if(el.id==='compare-left'||el.id==='compare-right'){FeatureKit[el.id==='compare-left'?'leftDoc':'rightDoc']=el.value;render();}
  if(el.id==='timeline-record'){FeatureKit.timelineBill=el.value;render();}
  if(el.id==='ocr-image'&&el.files[0])await FeatureKit.scanImage(el.files[0]);
  if(el.name==='billId'&&el.form?.dataset.kind==='activity'){const options=el.form.elements.documentId;options.innerHTML='<option value="">No document</option>'+FeatureData.documents(state).filter(d=>d.billId===el.value).map(d=>'<option value="'+esc(d.id)+'">'+esc(d.name)+'</option>').join('');}
  if(el.name==='patientChoice'){const manual=el.form?.querySelector('#new-patient-field'),input=el.form?.elements.patientNew;if(manual&&input){manual.hidden=el.value!=='other';input.disabled=el.value!=='other';input.required=el.value==='other';if(el.value==='other')input.focus();}}
  if(el.name==='memberId'&&el.form?.elements.patient){const m=state.members.find(m=>m.id===el.value);if(m)el.form.elements.patient.value=m.name;}
  if(el.id.startsWith('report-')||el.dataset.reportBill||el.dataset.reportDocument){
   const o=FeatureKit.report;
   if(el.id==='report-mode'){o.mode=el.value;o.billIds=null;}
   if(el.id==='report-period')FeatureKit.setReportPeriod(el.value);
   if(el.id==='report-member'){o.memberId=el.value;o.billIds=null;o.documentIds=[];}
   if(el.id==='report-from'||el.id==='report-to'){o[el.id.slice(7)]=el.value;o.period='custom';o.billIds=null;o.documentIds=[];}
   if(el.id==='report-notes')o.notes=el.checked;
   if(el.id==='report-timeline')o.timeline=el.checked;
   if(el.id==='report-all'){o.mode='selected';o.billIds=el.checked?null:[];}
   if(el.dataset.reportBill){o.mode='selected';const eligible=FeatureData.reportScope(state,{...o,billIds:null});if(o.billIds===null)o.billIds=eligible.bills.map(b=>b.id);o.billIds=el.checked?[...new Set([...o.billIds,el.dataset.reportBill])]:o.billIds.filter(id=>id!==el.dataset.reportBill);}
   if(el.dataset.reportDocument)o.documentIds=el.checked?[...new Set([...o.documentIds,el.dataset.reportDocument])]:o.documentIds.filter(id=>id!==el.dataset.reportDocument);
   const validDocs=new Set(FeatureData.documents(FeatureData.reportScope(state,o)).map(d=>d.id));o.documentIds=o.documentIds.filter(id=>validDocs.has(id));render();
  }
 }catch(err){toast(err.message);}
});
for(const event of ['pointerdown','keydown'])document.addEventListener(event,()=>FeatureKit.touch(),{passive:true});

FeatureKit.prepareExamples=async function(value){
 const loaded=FeatureData.prepare(value);
 if(loaded.demo&&!loaded.sampleEOBs){for(const b of loaded.bills.slice(0,3)){loaded.documents.push({id:'sample-eob-'+b.id,billId:b.id,type:'EOB',name:'sample-eob-'+b.id+'.pdf',mime:'application/pdf',data:await FeaturePDF.exampleEOB(b,T.currency(loaded)),date:T.today(),notes:'Fictional EOB for side-by-side comparison.'});}loaded.sampleEOBs=1;}
 return T.validate(loaded);
};
